/**
 * @summary Get total match count (fast, uses cache)
 */
export const GetMatchCountQueryParams = zod.object({
  resinCategory: zod.coerce.string().optional(),
});

export const GetMatchCountResponse = zod.object({
  count: zod.number(),
});

/**
 * @summary Get per-entry match counts for row badges
 */
export const GetMatchCountByEntryQueryParams = zod.object({
  resinCategory: zod.coerce.string().optional(),
});

export const GetMatchCountByEntryResponse = zod.record(
  zod.string(),
  zod.number(),
);

/**
 * @summary Request a presigned URL for file upload
 */
export const RequestUploadUrlBody = zod.object({
  name: zod.string(),
  size: zod.number(),
  contentType: zod.string(),
});

export const RequestUploadUrlResponse = zod.object({
  uploadURL: zod.string().url(),
  objectPath: zod.string(),
  metadata: zod
    .object({
      name: zod.string(),
      size: zod.number(),
      contentType: zod.string(),
    })
    .optional(),
});

/**
 * @summary Serve an object entity
 */
export const GetObjectParams = zod.object({
  objectPath: zod.coerce.string(),
});
